static int mt_cfg80211_vndr_cmd_reply_msg(
	struct wiphy *wiphy, unsigned int attr_cmd, void *data, unsigned int data_len)
{
	struct sk_buff *skb;
	int ret;

	if (!data) {
		MT_DEBUG_TRACE("data pointer is NULL\n");
		return -ENOMEM;
	}
#ifdef __MOCK
	return 0;
#endif

	skb = cfg80211_vendor_cmd_alloc_reply_skb(wiphy, data_len);
	if (!skb) {
		MT_DEBUG_TRACE("fail to allocate reply msg\n");
		return -ENOMEM;
	}

	if (nla_put(skb, attr_cmd, data_len, data)) {
		MT_DEBUG_TRACE("fail to put nla to skb\n");
		dev_kfree_skb(skb);
		return -EINVAL;
	}

	ret = cfg80211_vendor_cmd_reply(skb);
	if (ret) {
		MT_DEBUG_TRACE("reply msg failed\n");
		return -EINVAL;
	}

	return 0;
}

int mt_cfg80211_vndr_cmd_handler(
	struct wiphy *wiphy,
	struct wireless_dev *wifi_dev,
	enum mt_cfg80211_vndr_attr_type vndr_attr_type,
	struct mt_cfg80211_vndr_ctrl *data)
{
	struct mt_os_wifi_ioctl_cmd_cfg IoctlConfig, *pIoctlConfig = &IoctlConfig;
	int ret;
	struct mt_cfg80211_priv *mt_priv;
	struct mt_net_dev_priv *net_priv_info = NULL;
	struct net_device *net_dev;

	mt_priv = (struct mt_cfg80211_priv *)(wiphy_priv(wiphy));
	if (!mt_priv) {
		MT_DEBUG_TRACE("no mt priv");
		return -ENETDOWN;
	}
	if (wifi_dev)
		net_dev = wifi_dev->netdev;
	else
		net_dev = mt_priv->net_dev;

	net_priv_info = (struct mt_net_dev_priv *)netdev_priv((struct net_device *)net_dev);
	if (!net_priv_info)
		return -ENETDOWN;
	if (!net_priv_info->ioctl)
		return -ENETDOWN;
	pIoctlConfig->net_dev = net_dev;
	pIoctlConfig->priv_flags = mt_os_net_dev_get_priv_flags(net_dev);
	pIoctlConfig->cmd = MT_IO_CFG80211_VNDR;
	pIoctlConfig->subcmd = vndr_attr_type;
	pIoctlConfig->data = data;
	ret = net_priv_info->ioctl(net_dev, pIoctlConfig);
	return ret;
}

int mt_cfg80211_vndr_cmd_get_handler(
	struct wiphy *wiphy,
	struct wireless_dev *wifi_dev,
	enum mt_cfg80211_vndr_attr_type vndr_attr_type,
	unsigned int attr_cmd,
	struct mt_cfg80211_vndr_ctrl *ctrl_data_ptr)
{
	int ret;
	struct sk_buff *skb;

	ctrl_data_ptr->rsp_data = (void *)kmalloc(MT_MAX_VENDOR_MSG_LEN, GFP_ATOMIC);
	if (ctrl_data_ptr->rsp_data == NULL)
		return -EFAULT;
	memset(ctrl_data_ptr->rsp_data, 0x00, MT_MAX_VENDOR_MSG_LEN);
	ctrl_data_ptr->rsp_data_len = MT_MAX_VENDOR_MSG_LEN;
	ctrl_data_ptr->sub_id = attr_cmd;
	ret = mt_cfg80211_vndr_cmd_handler(
		wiphy, wifi_dev, vndr_attr_type, ctrl_data_ptr);
	if (ret)
		MT_DEBUG_TRACE("get failed.(vndr_attr_type=%d, attr_cmd=%d)\n",
			vndr_attr_type, attr_cmd);
	else {

#ifdef __MOCK
		if (ctrl_data_ptr->rsp_data)
			kfree(ctrl_data_ptr->rsp_data);
		return 0;
#endif /* __MOCK */
		skb = cfg80211_vendor_cmd_alloc_reply_skb(wiphy, ctrl_data_ptr->rsp_data_len);
		if (!skb) {
			MT_DEBUG_TRACE("fail to allocate reply msg\n");
			ret = -ENOMEM;
			goto out;
		}
		if (nla_put(
			skb, attr_cmd, ctrl_data_ptr->rsp_data_len, ctrl_data_ptr->rsp_data)) {
			MT_DEBUG_TRACE("fail to put nla to skb\n");
			dev_kfree_skb(skb);
			ret = -EINVAL;
			goto out;
		}

		ret = cfg80211_vendor_cmd_reply(skb);
		if (ret) {
			MT_DEBUG_TRACE("reply msg failed\n");
			ret = -EINVAL;
			goto out;
		}
	}
out:
	if (ctrl_data_ptr->rsp_data)
		kfree(ctrl_data_ptr->rsp_data);
	return ret;
}

