int mtk_cfg80211_vndr_doit_get_ftm_stat(
	struct wiphy *wiphy, struct wireless_dev *wifi_dev, const void *data, int len)
{
	int ret = 0;
	struct nlattr *tb[MTK_NL80211_VENDOR_ATTR_BSS_STATS_ATTR_MAX + 1];
	struct mt_cfg80211_vndr_ctrl ctrl_data, *ctrl_data_ptr = &ctrl_data;

	if (!wifi_dev) {
		MT_DEBUG_TRACE("wdev is NULL\n");
		return -EFAULT;
	}

	ret = nla_parse(tb, MTK_NL80211_VENDOR_ATTR_FTM_STAT_MAX, (struct nlattr *)data,
		len, MTK_SUBCMD_FTM_STAT_POLICY, NULL);

	if (ret) {
		MT_DEBUG_TRACE("nla_parse error\n");
		return -EINVAL;
	}

	if (tb[MTK_NL80211_VENDOR_ATTR_FTM_STAT_STR]) {
		ctrl_data_ptr->u8_val = nla_get_u8(tb[MTK_NL80211_VENDOR_ATTR_FTM_STAT_STR]);
		ret = mt_cfg80211_vndr_cmd_get_handler(
			wiphy, wifi_dev, mt_cfg80211_vndr_attr_set_get_ftm_stat,
			MTK_NL80211_VENDOR_ATTR_FTM_STAT_STR, ctrl_data_ptr);
	}

	return ret;
}

int mtk_cfg80211_vndr_doit_set_ap_wireless(
	struct wiphy *wiphy, struct wireless_dev *wifi_dev, const void *data, int len)
{
	struct nlattr *tb[MTK_NL80211_VENDOR_ATTR_AP_WIRELESS_MAX + 1];
	int ret;
	char temp_buf[64] = "\0";
	struct mt_cfg80211_vndr_ctrl ctrl_data, *ctrl_data_ptr = &ctrl_data;

	if (!wifi_dev) {
		MT_DEBUG_TRACE("wdev is NULL\n");
		return -EFAULT;
	}

	ret = nla_parse(tb, MTK_NL80211_VENDOR_ATTR_AP_WIRELESS_MAX, (struct nlattr *)data,
		len, MTK_SUBCMD_AP_WIRELESS_POLICY, NULL);

	if (ret) {
		MT_DEBUG_TRACE("nla_parse error\n");
		return -EINVAL;
	}

	if (tb[MTK_NL80211_VENDOR_ATTR_AP_WIRELESS_FIXED_MCS]) {
		ctrl_data_ptr->u8_val = nla_get_u8(tb[MTK_NL80211_VENDOR_ATTR_AP_WIRELESS_FIXED_MCS]);
		ctrl_data_ptr->sub_id = MTK_NL80211_VENDOR_ATTR_AP_WIRELESS_FIXED_MCS;
		ret = mt_cfg80211_vndr_cmd_handler(
			wiphy, wifi_dev, mt_cfg80211_vndr_attr_set_set_ap_wireless, ctrl_data_ptr);
		MT_DEBUG_TRACE("mcs %d\n", ctrl_data_ptr->u8_val);
	}

	if (tb[MTK_NL80211_VENDOR_ATTR_AP_WIRELESS_FIXED_OFDMA]) {
		ctrl_data_ptr->u8_val = nla_get_u8(tb[MTK_NL80211_VENDOR_ATTR_AP_WIRELESS_FIXED_OFDMA]);
		ctrl_data_ptr->sub_id = MTK_NL80211_VENDOR_ATTR_AP_WIRELESS_FIXED_OFDMA;
		ret = mt_cfg80211_vndr_cmd_handler(
			wiphy, wifi_dev, mt_cfg80211_vndr_attr_set_set_ap_wireless, ctrl_data_ptr);
		MT_DEBUG_TRACE("ofdma %d\n", ctrl_data_ptr->u8_val);
	}

	if (tb[MTK_NL80211_VENDOR_ATTR_AP_WIRELESS_PPDU_TX_TYPE]) {
		ctrl_data_ptr->u8_val = nla_get_u8(tb[MTK_NL80211_VENDOR_ATTR_AP_WIRELESS_PPDU_TX_TYPE]);
		ctrl_data_ptr->sub_id = MTK_NL80211_VENDOR_ATTR_AP_WIRELESS_PPDU_TX_TYPE;
		ret = mt_cfg80211_vndr_cmd_handler(
			wiphy, wifi_dev, mt_cfg80211_vndr_attr_set_set_ap_wireless, ctrl_data_ptr);
		MT_DEBUG_TRACE("ppdu_type %d\n", ctrl_data_ptr->u8_val);
	}

	if (tb[MTK_NL80211_VENDOR_ATTR_AP_WIRELESS_NUSERS_OFDMA]) {
		ctrl_data_ptr->u8_val = nla_get_u8(tb[MTK_NL80211_VENDOR_ATTR_AP_WIRELESS_NUSERS_OFDMA]);
		ctrl_data_ptr->sub_id = MTK_NL80211_VENDOR_ATTR_AP_WIRELESS_NUSERS_OFDMA;
		ret = mt_cfg80211_vndr_cmd_handler(
			wiphy, wifi_dev, mt_cfg80211_vndr_attr_set_set_ap_wireless, ctrl_data_ptr);
		MT_DEBUG_TRACE("nuser_ofdma %d\n", ctrl_data_ptr->u8_val);
	}

	if (tb[MTK_NL80211_VENDOR_ATTR_AP_WIRELESS_BA_BUFFER_SIZE]) {
		ctrl_data_ptr->ushort_val =
			nla_get_u16(tb[MTK_NL80211_VENDOR_ATTR_AP_WIRELESS_BA_BUFFER_SIZE]);
		ctrl_data_ptr->sub_id = MTK_NL80211_VENDOR_ATTR_AP_WIRELESS_BA_BUFFER_SIZE;
		ret = mt_cfg80211_vndr_cmd_handler(
			wiphy, wifi_dev, mt_cfg80211_vndr_attr_set_set_ap_wireless, ctrl_data_ptr);
		MT_DEBUG_TRACE("ba_buff_size %d\n", ctrl_data_ptr->ushort_val);
	}

	if (tb[MTK_NL80211_VENDOR_ATTR_AP_WIRELESS_MIMO]) {
		ctrl_data_ptr->u8_val = nla_get_u8(tb[MTK_NL80211_VENDOR_ATTR_AP_WIRELESS_MIMO]);
		ctrl_data_ptr->sub_id = MTK_NL80211_VENDOR_ATTR_AP_WIRELESS_MIMO;
		ret = mt_cfg80211_vndr_cmd_handler(
			wiphy, wifi_dev, mt_cfg80211_vndr_attr_set_set_ap_wireless, ctrl_data_ptr);
		MT_DEBUG_TRACE("mimo %d\n", ctrl_data_ptr->u8_val);
	}

	if (tb[MTK_NL80211_VENDOR_ATTR_AP_WIRELESS_AMPDU]) {
		ctrl_data_ptr->u8_val = nla_get_u8(tb[MTK_NL80211_VENDOR_ATTR_AP_WIRELESS_AMPDU]);
		ctrl_data_ptr->sub_id = MTK_NL80211_VENDOR_ATTR_AP_WIRELESS_AMPDU;
		ret = mt_cfg80211_vndr_cmd_handler(
			wiphy, wifi_dev, mt_cfg80211_vndr_attr_set_set_ap_wireless, ctrl_data_ptr);
		MT_DEBUG_TRACE("ampdu %d\n", ctrl_data_ptr->u8_val);
	}

	if (tb[MTK_NL80211_VENDOR_ATTR_AP_WIRELESS_AMSDU]) {
		ctrl_data_ptr->u8_val = nla_get_u8(tb[MTK_NL80211_VENDOR_ATTR_AP_WIRELESS_AMSDU]);
		ctrl_data_ptr->sub_id = MTK_NL80211_VENDOR_ATTR_AP_WIRELESS_AMSDU;
		ret = mt_cfg80211_vndr_cmd_handler(
			wiphy, wifi_dev, mt_cfg80211_vndr_attr_set_set_ap_wireless, ctrl_data_ptr);
		MT_DEBUG_TRACE("amsdu %d\n", ctrl_data_ptr->u8_val);
	}

	if (tb[MTK_NL80211_VENDOR_ATTR_AP_WIRELESS_CERT]) {
#if KERNEL_VERSION(5, 15, 0) > LINUX_VERSION_CODE
		nla_strlcpy(temp_buf, tb[MTK_NL80211_VENDOR_ATTR_AP_WIRELESS_CERT],
					ARRAY_SIZE(temp_buf));
#else
		nla_strscpy(temp_buf, tb[MTK_NL80211_VENDOR_ATTR_AP_WIRELESS_CERT],
					ARRAY_SIZE(temp_buf));
#endif
		MT_DEBUG_TRACE("cert %s\n", temp_buf);
		ctrl_data_ptr->data = &temp_buf[0];

		ctrl_data_ptr->sub_id = MTK_NL80211_VENDOR_ATTR_AP_WIRELESS_CERT;
		ret = mt_cfg80211_vndr_cmd_handler(
			wiphy, wifi_dev, mt_cfg80211_vndr_attr_set_set_ap_wireless, ctrl_data_ptr);
	}

	if (tb[MTK_NL80211_VENDOR_ATTR_AP_WIRELESS_HE_TXOP_RTS_THLD]) {
		ctrl_data_ptr->ushort_val = nla_get_u16(
				tb[MTK_NL80211_VENDOR_ATTR_AP_WIRELESS_HE_TXOP_RTS_THLD]);
		ctrl_data_ptr->sub_id = MTK_NL80211_VENDOR_ATTR_AP_WIRELESS_HE_TXOP_RTS_THLD;
		ret = mt_cfg80211_vndr_cmd_handler(
			wiphy, wifi_dev, mt_cfg80211_vndr_attr_set_set_ap_wireless, ctrl_data_ptr);
		MT_DEBUG_TRACE("he_txop_rts_thld = %d\n", ctrl_data_ptr->ushort_val);
	}

	return 0;
}

int mtk_cfg80211_vndr_doit_set_ap_rfeature(
	struct wiphy *wiphy, struct wireless_dev *wifi_dev, const void *data, int len)
{
	int ret;
	struct nlattr *tb[MTK_NL80211_VENDOR_AP_RFEATURE_ATTR_MAX + 1];
	char temp_buf[64] = "\0";
	struct mt_cfg80211_vndr_ctrl ctrl_data, *ctrl_data_ptr = &ctrl_data;

	if (!wifi_dev) {
		MT_DEBUG_TRACE("wdev is NULL\n");
		return -EFAULT;
	}

	ret = nla_parse(tb, MTK_NL80211_VENDOR_AP_RFEATURE_ATTR_MAX, (struct nlattr *)data,
		len, MTK_SUBCMD_AP_RFEATURE_POLICY, NULL);

	if (ret) {
		MT_DEBUG_TRACE("nla_parse error\n");
		return -EINVAL;
	}

	if (tb[MTK_NL80211_VENDOR_ATTR_AP_RFEATURE_HE_GI]) {
		ctrl_data_ptr->u8_val = nla_get_u8(tb[MTK_NL80211_VENDOR_ATTR_AP_RFEATURE_HE_GI]);
		ctrl_data_ptr->sub_id = MTK_NL80211_VENDOR_ATTR_AP_RFEATURE_HE_GI;
		ret = mt_cfg80211_vndr_cmd_handler(
			wiphy, wifi_dev, mt_cfg80211_vndr_attr_set_ap_rfeature, ctrl_data_ptr);
		MT_DEBUG_TRACE("gi %d\n", ctrl_data_ptr->u8_val);
	}

	if (tb[MTK_NL80211_VENDOR_ATTR_AP_RFEATURE_HE_LTF]) {
		ctrl_data_ptr->u8_val = nla_get_u8(tb[MTK_NL80211_VENDOR_ATTR_AP_RFEATURE_HE_LTF]);
		ctrl_data_ptr->sub_id = MTK_NL80211_VENDOR_ATTR_AP_RFEATURE_HE_LTF;
		ret = mt_cfg80211_vndr_cmd_handler(
			wiphy, wifi_dev, mt_cfg80211_vndr_attr_set_ap_rfeature, ctrl_data_ptr);
		MT_DEBUG_TRACE("ltf %d\n", ctrl_data_ptr->u8_val);
	}

	if (tb[MTK_NL80211_VENDOR_ATTR_AP_RFEATURE_TRIG_TYPE]) {
#if KERNEL_VERSION(5, 15, 0) > LINUX_VERSION_CODE
		nla_strlcpy(temp_buf, tb[MTK_NL80211_VENDOR_ATTR_AP_RFEATURE_TRIG_TYPE],
					ARRAY_SIZE(temp_buf));
#else
		nla_strscpy(temp_buf, tb[MTK_NL80211_VENDOR_ATTR_AP_RFEATURE_TRIG_TYPE],
					ARRAY_SIZE(temp_buf));
#endif
		if (strlen(temp_buf) >= nla_len(tb[MTK_NL80211_VENDOR_ATTR_AP_RFEATURE_TRIG_TYPE]))
			return -EINVAL;
		MT_DEBUG_TRACE("trig_cfg %s\n", temp_buf);
		ctrl_data_ptr->data = &temp_buf[0];
		ctrl_data_ptr->sub_id = MTK_NL80211_VENDOR_ATTR_AP_RFEATURE_TRIG_TYPE;
		ret = mt_cfg80211_vndr_cmd_handler(
			wiphy, wifi_dev, mt_cfg80211_vndr_attr_set_ap_rfeature, ctrl_data_ptr);
	}

	if (tb[MTK_NL80211_VENDOR_ATTR_AP_RFEATURE_ACK_PLCY]) {
		ctrl_data_ptr->u8_val = nla_get_u8(tb[MTK_NL80211_VENDOR_ATTR_AP_RFEATURE_ACK_PLCY]);
		ctrl_data_ptr->sub_id = MTK_NL80211_VENDOR_ATTR_AP_RFEATURE_ACK_PLCY;
		ret = mt_cfg80211_vndr_cmd_handler(
			wiphy, wifi_dev, mt_cfg80211_vndr_attr_set_ap_rfeature, ctrl_data_ptr);
		MT_DEBUG_TRACE("ack_plcy %d\n", ctrl_data_ptr->u8_val);
	}

	if (tb[MTK_NL80211_VENDOR_ATTR_AP_RFEATURE_PPDU_TYPE]) {
		ctrl_data_ptr->u8_val = nla_get_u8(tb[MTK_NL80211_VENDOR_ATTR_AP_RFEATURE_PPDU_TYPE]);
		ctrl_data_ptr->sub_id = MTK_NL80211_VENDOR_ATTR_AP_RFEATURE_PPDU_TYPE;
		ret = mt_cfg80211_vndr_cmd_handler(
			wiphy, wifi_dev, mt_cfg80211_vndr_attr_set_ap_rfeature, ctrl_data_ptr);
		MT_DEBUG_TRACE("ppdu_type %d\n", ctrl_data_ptr->u8_val);
	}
	
	if (tb[MTK_NL80211_VENDOR_ATTR_AP_RFEATURE_HE_TXOP_RTS_THLD]) {
		ctrl_data_ptr->ushort_val = nla_get_u16(tb[MTK_NL80211_VENDOR_ATTR_AP_RFEATURE_HE_TXOP_RTS_THLD]);
		ctrl_data_ptr->sub_id = MTK_NL80211_VENDOR_ATTR_AP_RFEATURE_HE_TXOP_RTS_THLD;
		ret = mt_cfg80211_vndr_cmd_handler(
			wiphy, wifi_dev, mt_cfg80211_vndr_attr_set_ap_rfeature, ctrl_data_ptr);
		MT_DEBUG_TRACE("ppdu_type %d\n", ctrl_data_ptr->ushort_val);
	}

	if (tb[MTK_NL80211_VENDOR_ATTR_AP_RFEATURE_EXTRA_LTF_DISABLE]) {
		ctrl_data_ptr->u8_val =
			nla_get_u8(tb[MTK_NL80211_VENDOR_ATTR_AP_RFEATURE_EXTRA_LTF_DISABLE]);
		ctrl_data_ptr->sub_id = MTK_NL80211_VENDOR_ATTR_AP_RFEATURE_EXTRA_LTF_DISABLE;
		ret = mt_cfg80211_vndr_cmd_handler(
			wiphy, wifi_dev, mt_cfg80211_vndr_attr_set_ap_rfeature, ctrl_data_ptr);
		MT_DEBUG_TRACE("disable %d\n", ctrl_data_ptr->u8_val);
	}

	if (tb[MTK_NL80211_VENDOR_ATTR_AP_RFEATURE_EXTRA_LTF]) {
		ctrl_data_ptr->u8_val =
			nla_get_u8(tb[MTK_NL80211_VENDOR_ATTR_AP_RFEATURE_EXTRA_LTF]);
		ctrl_data_ptr->sub_id = MTK_NL80211_VENDOR_ATTR_AP_RFEATURE_EXTRA_LTF;
		ret = mt_cfg80211_vndr_cmd_handler(
			wiphy, wifi_dev, mt_cfg80211_vndr_attr_set_ap_rfeature, ctrl_data_ptr);
		MT_DEBUG_TRACE("extra_ltf %d\n", ctrl_data_ptr->u8_val);
	}
	return 0;
}

int mtk_cfg80211_vndr_doit_set_country(
	struct wiphy *wiphy, struct wireless_dev *wifi_dev, const void *data, int len)
{
	struct nlattr *tb[MTK_NL80211_VENDOR_ATTR_COUNTRY_MAX + 1];
	int ret = 0;
	struct mt_cfg80211_vndr_ctrl ctrl_data, *ctrl_data_ptr = &ctrl_data;

	MT_DEBUG_TRACE("====>\n");

	ret = nla_parse(tb, MTK_NL80211_VENDOR_ATTR_COUNTRY_MAX, (struct nlattr *)data,
		len, MTK_SUBCMD_SET_COUNTRY_POLICY, NULL);
	if (ret) {
		MT_DEBUG_TRACE("nla_parse failed.\n");
		return -EINVAL;
	}

	if (tb[MTK_NL80211_VENDOR_ATTR_COUNTRY_SET_CODE]) {
		ctrl_data_ptr->data = nla_data(tb[MTK_NL80211_VENDOR_ATTR_COUNTRY_SET_CODE]);
		ctrl_data_ptr->data_len = nla_len(tb[MTK_NL80211_VENDOR_ATTR_COUNTRY_SET_CODE]);
		ctrl_data_ptr->sub_id = MTK_NL80211_VENDOR_ATTR_COUNTRY_SET_CODE;
		if (strlen(ctrl_data_ptr->data) <= ctrl_data_ptr->data_len)
			ret = mt_cfg80211_vndr_cmd_handler(
				wiphy, wifi_dev,
				mt_cfg80211_vndr_attr_set_country, ctrl_data_ptr);
	}

	if (tb[MTK_NL80211_VENDOR_ATTR_COUNTRY_SET_REGION]) {
		ctrl_data_ptr->uint_val = nla_get_u32(tb[MTK_NL80211_VENDOR_ATTR_COUNTRY_SET_REGION]);
		ctrl_data_ptr->sub_id = MTK_NL80211_VENDOR_ATTR_COUNTRY_SET_REGION;
		ret = mt_cfg80211_vndr_cmd_handler(
			wiphy, wifi_dev, mt_cfg80211_vndr_attr_set_country, ctrl_data_ptr);
	}

	if (tb[MTK_NL80211_VENDOR_ATTR_COUNTRY_SET_NAME]) {
		ctrl_data_ptr->data = nla_data(tb[MTK_NL80211_VENDOR_ATTR_COUNTRY_SET_NAME]);
		ctrl_data_ptr->data_len = nla_len(tb[MTK_NL80211_VENDOR_ATTR_COUNTRY_SET_NAME]);
		ctrl_data_ptr->sub_id = MTK_NL80211_VENDOR_ATTR_COUNTRY_SET_NAME;
		if (strlen(ctrl_data_ptr->data) <= ctrl_data_ptr->data_len)
			ret = mt_cfg80211_vndr_cmd_handler(
				wiphy, wifi_dev,
				mt_cfg80211_vndr_attr_set_country, ctrl_data_ptr);
	}

	return ret;
}

int mtk_cfg80211_vndr_doit_set_channel(
	struct wiphy *wiphy, struct wireless_dev *wifi_dev, const void *data, int len)
{
	struct nlattr *tb[MTK_NL80211_VENDOR_ATTR_CHAN_MAX + 1];
	int ret = 0;
	struct mt_cfg80211_vndr_ctrl ctrl_data, *ctrl_data_ptr = &ctrl_data;
	struct mt_ch_switch_param ch_switch_params;
	struct mt_ch_switch_param *ch_switch_params_ptr = &ch_switch_params;
	unsigned int freq = 0;

	memset(&ctrl_data, 0, sizeof(ctrl_data));
	memset(&ch_switch_params, 0, sizeof(ch_switch_params));

	ret = nla_parse(tb, MTK_NL80211_VENDOR_ATTR_CHAN_MAX, (struct nlattr *)data,
		len, MTK_SUBCMD_SET_CHANNEL_POLICY, NULL);
	if (ret) {
		MT_DEBUG_TRACE("nla_parse failed.\n");
		return -EINVAL;
	}

	if (tb[MTK_NL80211_VENDOR_ATTR_CHAN_SET_NUM]) {
		ch_switch_params_ptr->ch = nla_get_u8(tb[MTK_NL80211_VENDOR_ATTR_CHAN_SET_NUM]);
		ch_switch_params_ptr->flags |= 1 << MTK_NL80211_VENDOR_ATTR_CHAN_SET_NUM;
	} else if (tb[MTK_NL80211_VENDOR_ATTR_CHAN_SET_FREQ]) {
		freq = nla_get_u32(tb[MTK_NL80211_VENDOR_ATTR_CHAN_SET_FREQ]);
		ch_switch_params_ptr->ch = ieee80211_frequency_to_channel(freq);
		ch_switch_params_ptr->flags |= 1 << MTK_NL80211_VENDOR_ATTR_CHAN_SET_NUM;
	}

	if (tb[MTK_NL80211_VENDOR_ATTR_CHAN_SET_BW]) {
		ch_switch_params_ptr->bw = nla_get_u32(tb[MTK_NL80211_VENDOR_ATTR_CHAN_SET_BW]);
		ch_switch_params_ptr->flags |= 1 << MTK_NL80211_VENDOR_ATTR_CHAN_SET_BW;
	}

	if (tb[MTK_NL80211_VENDOR_ATTR_CHAN_SET_HT_EXTCHAN]) {
		ch_switch_params_ptr->ext_ch = nla_get_u8(tb[MTK_NL80211_VENDOR_ATTR_CHAN_SET_HT_EXTCHAN]);
		ch_switch_params_ptr->flags |= 1 << MTK_NL80211_VENDOR_ATTR_CHAN_SET_HT_EXTCHAN;
	}

	if (tb[MTK_NL80211_VENDOR_ATTR_CHAN_SET_HT_COEX]) {
		ch_switch_params_ptr->ht_coex = nla_get_u8(tb[MTK_NL80211_VENDOR_ATTR_CHAN_SET_HT_COEX]);
		ch_switch_params_ptr->flags |= 1 << MTK_NL80211_VENDOR_ATTR_CHAN_SET_HT_COEX;
	}

	if (tb[MTK_NL80211_VENDOR_ATTR_CHAN_SET_BYPASS_CAC]) {
		ch_switch_params_ptr->cac_required = nla_get_u8(tb[MTK_NL80211_VENDOR_ATTR_CHAN_SET_BYPASS_CAC]);
		ch_switch_params_ptr->flags |= 1 << MTK_NL80211_VENDOR_ATTR_CHAN_SET_BYPASS_CAC;
	}

	if (ch_switch_params_ptr->flags == 0)
		return -EINVAL;

	ctrl_data_ptr->data = ch_switch_params_ptr;
	ctrl_data_ptr->data_len = sizeof(*ch_switch_params_ptr);
	ret = mt_cfg80211_vndr_cmd_handler(
		wiphy, wifi_dev, mt_cfg80211_vndr_attr_set_channel, ctrl_data_ptr);

	return ret;
}

int mtk_cfg80211_vndr_doit_set_acl(
	struct wiphy *wiphy, struct wireless_dev *wifi_dev, const void *data, int len)
{
	struct nlattr *tb[MTK_NL80211_VENDOR_AP_ACL_ATTR_MAX + 1];
	int ret;
	struct mt_cfg80211_vndr_ctrl ctrl_data, *ctrl_data_ptr = &ctrl_data;

	if (!wifi_dev) {
		MT_DEBUG_TRACE("wdev is NULL\n");
		return -EFAULT;
	}

	ret = nla_parse(tb, MTK_NL80211_VENDOR_AP_ACL_ATTR_MAX, (struct nlattr *)data,
		len, MTK_SUBCMD_SET_ACL_POLICY, NULL);

	if (ret)
		return -EINVAL;

	if (tb[MTK_NL80211_VENDOR_ATTR_ACL_POLICY]) {
		ctrl_data_ptr->u8_val = nla_get_u8(tb[MTK_NL80211_VENDOR_ATTR_ACL_POLICY]);
		ctrl_data_ptr->sub_id = MTK_NL80211_VENDOR_ATTR_ACL_POLICY;
		ret = mt_cfg80211_vndr_cmd_handler(
			wiphy, wifi_dev, mt_cfg80211_vndr_attr_set_acl_policy, ctrl_data_ptr);
		if (ret < 0)
			return ret;
	}

	if (tb[MTK_NL80211_VENDOR_ATTR_ACL_ADD_MAC]) {
		int len;

		len = nla_len(tb[MTK_NL80211_VENDOR_ATTR_ACL_ADD_MAC]);
		ctrl_data_ptr->data = nla_data(tb[MTK_NL80211_VENDOR_ATTR_ACL_ADD_MAC]);

		if (len <= 0)
			return -EINVAL;
		ctrl_data_ptr->data_len = len;
		ctrl_data_ptr->sub_id = MTK_NL80211_VENDOR_ATTR_ACL_ADD_MAC;
		ret = mt_cfg80211_vndr_cmd_handler(
			wiphy, wifi_dev, mt_cfg80211_vndr_attr_set_acl_policy, ctrl_data_ptr);
		if (ret < 0)
			return ret;
	}

	if (tb[MTK_NL80211_VENDOR_ATTR_ACL_DEL_MAC]) {
		int len;

		len = nla_len(tb[MTK_NL80211_VENDOR_ATTR_ACL_DEL_MAC]);
		ctrl_data_ptr->data = nla_data(tb[MTK_NL80211_VENDOR_ATTR_ACL_DEL_MAC]);

		if (len <= 0)
			return -EINVAL;
		ctrl_data_ptr->data_len = len;
		ctrl_data_ptr->sub_id = MTK_NL80211_VENDOR_ATTR_ACL_DEL_MAC;
		ret = mt_cfg80211_vndr_cmd_handler(
			wiphy, wifi_dev, mt_cfg80211_vndr_attr_set_acl_policy, ctrl_data_ptr);
		if (ret < 0)
			return ret;
	}

	if (tb[MTK_NL80211_VENDOR_ATTR_ACL_SHOW_ALL]) {
		ret = mt_cfg80211_vndr_cmd_get_handler(
			wiphy, wifi_dev, mt_cfg80211_vndr_attr_set_acl_policy,
			MTK_NL80211_VENDOR_ATTR_ACL_LIST_INFO,
			ctrl_data_ptr);
		if (ret < 0)
			return ret;
	}

	if (tb[MTK_NL80211_VENDOR_ATTR_ACL_CLEAR_ALL]) {
		ctrl_data_ptr->sub_id = MTK_NL80211_VENDOR_ATTR_ACL_CLEAR_ALL;
		ret = mt_cfg80211_vndr_cmd_handler(
			wiphy, wifi_dev, mt_cfg80211_vndr_attr_set_acl_policy, ctrl_data_ptr);
		if (ret < 0)
			return ret;
	}

	return 0;
}

