int mtk_cfg80211_vndr_doit_set_radio_stats(
	struct wiphy *wiphy, struct wireless_dev *wifi_dev, const void *data, int len)
{
	int ret = 0;
	struct net_device *net_dev;
	struct nlattr *tb[MTK_NL80211_VENDOR_ATTR_RADIO_SET_STATS_ATTR_MAX + 1];
	struct mt_cfg80211_vndr_ctrl ctrl_data, *ctrl_data_ptr = &ctrl_data;

	if (!wifi_dev) {
		MT_DEBUG_TRACE("wdev is NULL\n");
		return -EFAULT;
	}
	net_dev = wifi_dev->netdev;
	if (!net_dev) {
		MT_DEBUG_TRACE("net_dev is NULL\n");
		return -EFAULT;
	}
	MT_DEBUG_TRACE("ifname: %s, iftype: %d\n", net_dev->name, wifi_dev->iftype);

	ret = nla_parse(tb, MTK_NL80211_VENDOR_ATTR_RADIO_SET_STATS_ATTR_MAX,
		(struct nlattr *)data, len, MTK_SUBCMD_SET_RADIO_STATS_POLICY, NULL);
	if (ret) {
		MT_DEBUG_TRACE("nla_parse failed. ret=%x.\n", ret);
		return -EINVAL;
	}

	if (tb[MTK_NL80211_VENDOR_ATTR_RADIO_SET_STATS_MEASURING_METHOD]) {
		ctrl_data_ptr->data =
			nla_data(tb[MTK_NL80211_VENDOR_ATTR_RADIO_SET_STATS_MEASURING_METHOD]);
		if (!ctrl_data_ptr->data)
			return -EINVAL;
		ctrl_data_ptr->data_len =
			nla_len(tb[MTK_NL80211_VENDOR_ATTR_RADIO_SET_STATS_MEASURING_METHOD]);
		ctrl_data_ptr->sub_id = MTK_NL80211_VENDOR_ATTR_RADIO_SET_STATS_MEASURING_METHOD;
		ret = mt_cfg80211_vndr_cmd_handler(
			wiphy, wifi_dev, mt_cfg80211_vndr_attr_set_radio_stats, ctrl_data_ptr);
		if (ret)
			return -EINVAL;
	}

	if (tb[MTK_NL80211_VENDOR_ATTR_RADIO_SET_MEASURE_ENABEL]) {
		ctrl_data_ptr->u8_val =
			nla_get_u8(tb[MTK_NL80211_VENDOR_ATTR_RADIO_SET_MEASURE_ENABEL]);
		ctrl_data_ptr->sub_id = MTK_NL80211_VENDOR_ATTR_RADIO_SET_MEASURE_ENABEL;
		ret = mt_cfg80211_vndr_cmd_handler(
			wiphy, wifi_dev, mt_cfg80211_vndr_attr_set_radio_stats, ctrl_data_ptr);
		if (ret)
			return -EINVAL;
	}

	return 0;
}

int mtk_cfg80211_vndr_doit_get_radio_stats(
	struct wiphy *wiphy, struct wireless_dev *wifi_dev, const void *data, int len)
{
	struct net_device *net_dev;
	int ret = 0;
	struct nlattr *tb[MTK_NL80211_VENDOR_ATTR_RADIO_STATS_ATTR_MAX + 1];
	struct mt_cfg80211_vndr_ctrl ctrl_data, *ctrl_data_ptr = &ctrl_data;

	if (!wifi_dev) {
		MT_DEBUG_TRACE("wdev is NULL\n");
		return -EFAULT;
	}
	net_dev = wifi_dev->netdev;
	if (!net_dev) {
		MT_DEBUG_TRACE("net_dev is NULL\n");
		return -EFAULT;
	}
	MT_DEBUG_TRACE("ifname: %s, iftype: %d\n", net_dev->name, wifi_dev->iftype);

	ret = nla_parse(tb, MTK_NL80211_VENDOR_ATTR_RADIO_STATS_ATTR_MAX,
		(struct nlattr *)data, len, NULL, NULL);
	if (ret) {
		MT_DEBUG_TRACE("nla_parse failed. ret=%x.\n", ret);
		return -EINVAL;
	}
	if (tb[MTK_NL80211_VENDOR_ATTR_RADIO_STATS]) {
		ret = mt_cfg80211_vndr_cmd_get_handler(
			wiphy, wifi_dev, mt_cfg80211_vndr_attr_get_radio_stats,
			MTK_NL80211_VENDOR_ATTR_RADIO_STATS, ctrl_data_ptr);
		if (ret) {
			MT_DEBUG_TRACE("mtk_cfg80211_reply_radio_stats failed. ret=%x\n", ret);
			return -EINVAL;
		}
	}

	if (tb[MTK_NL80211_VENDOR_ATTR_GET_RADIO_CPU_TEMPRETURE]) {
		ctrl_data_ptr->uint_val = 0;
		ctrl_data_ptr->sub_id = MTK_NL80211_VENDOR_ATTR_GET_RADIO_CPU_TEMPRETURE;
		ret = mt_cfg80211_vndr_cmd_handler(
			wiphy, wifi_dev, mt_cfg80211_vndr_attr_get_radio_stats, ctrl_data_ptr);
		if (ret == 0)
			ret = mt_cfg80211_vndr_cmd_reply_msg(wiphy,
				MTK_NL80211_VENDOR_ATTR_GET_RADIO_CPU_TEMPRETURE,
				&ctrl_data_ptr->uint_val,
				sizeof(unsigned int));
		if (ret) {
			MT_DEBUG_TRACE("failed - [ERROR]nl80211_easymesh_sr_enable fail.\n");
			return -EINVAL;
		}
	}

#ifdef ANDLINK_V4_0
	if (tb[MTK_NL80211_VENDOR_ATTR_GET_RADIO_BSS_INFO_ANDLINK_FORMAT]) {
		ret = mt_cfg80211_vndr_cmd_get_handler(
			wiphy, wifi_dev, mt_cfg80211_vndr_attr_get_radio_stats,
			MTK_NL80211_VENDOR_ATTR_GET_RADIO_BSS_INFO_ANDLINK_FORMAT, ctrl_data_ptr);
		if (ret) {
			MT_DEBUG_TRACE("failed - [ERROR]reply_andlink_bss_info fail.\n");
			return -EINVAL;
		}
	}
#endif/*ANDLINK_V4_0*/

	if (tb[MTK_NL80211_VENDOR_ATTR_GET_RADIO_RSSI]) {
		ret = mt_cfg80211_vndr_cmd_get_handler(
			wiphy, wifi_dev, mt_cfg80211_vndr_attr_get_radio_stats,
			MTK_NL80211_VENDOR_ATTR_GET_RADIO_RSSI, ctrl_data_ptr);
		if (ret)
			return -EINVAL;
	}

	return 0;
}

