int mtk_cfg80211_vndr_set_ap_mld_index(
	struct wiphy *wiphy,
	struct wireless_dev *wifi_dev,
	struct nlattr *attr)
{
	int ret;
	struct mt_cfg80211_vndr_ctrl ctrl_data, *ctrl_data_ptr = &ctrl_data;

	ctrl_data_ptr->u8_val = nla_get_u8(attr);
	ctrl_data_ptr->sub_id = MTK_NL80211_VENDOR_ATTR_SET_AP_MLD_INDEX;

	ret = mt_cfg80211_vndr_cmd_handler(
		wiphy, wifi_dev, mt_cfg80211_vndr_attr_set_ap_mld, ctrl_data_ptr);
	if (ret < 0) {
		MT_DEBUG_TRACE("mt_cfg80211_vndr_cmd_handler for set ap mld index failed, ret:%d\n", ret);
		return ret;
	}

	return 0;
}

int mtk_cfg80211_vndr_set_ap_mld_addr(
	struct wiphy *wiphy,
	struct wireless_dev *wifi_dev,
	struct nlattr *data)
{
	struct nlattr *tb[MTK_NL80211_VENDOR_ATTR_AP_MLD_ATTR_MAX + 1];
	int ret;
	struct mt_cfg80211_vndr_ctrl ctrl_data, *ctrl_data_ptr = &ctrl_data;

	ret = nla_parse_nested(tb, MTK_NL80211_VENDOR_ATTR_AP_MLD_ATTR_MAX,
		(struct nlattr *)data, MTK_SUBCMD_SET_AP_MLD_ADDRESS_POLICY, NULL);

	if (ret) {
		MT_DEBUG_TRACE("mld addr parse failed, ret:%d\n", ret);
		return -EINVAL;
	}

        if (!tb[MTK_NL80211_VENDOR_ATTR_AP_MLD_INDEX] || !tb[MTK_NL80211_VENDOR_ATTR_AP_MLD_ADDRESS]) {
		MT_DEBUG_TRACE("mld group index or addr not exist\n");
		return -EINVAL;
	}

	ctrl_data_ptr->u8_val = nla_get_u8(tb[MTK_NL80211_VENDOR_ATTR_AP_MLD_INDEX]);
	ctrl_data_ptr->data_len = nla_len(tb[MTK_NL80211_VENDOR_ATTR_AP_MLD_ADDRESS]);
	ctrl_data_ptr->data = nla_data(tb[MTK_NL80211_VENDOR_ATTR_AP_MLD_ADDRESS]);
	ctrl_data_ptr->sub_id = MTK_NL80211_VENDOR_ATTR_SET_AP_MLD_ADDRESS;

	ret = mt_cfg80211_vndr_cmd_handler(
		wiphy, wifi_dev, mt_cfg80211_vndr_attr_set_ap_mld, ctrl_data_ptr);
	if (ret < 0) {
		MT_DEBUG_TRACE("mt_cfg80211_vndr_cmd_handler for set ap mld address failed, ret:%d\n", ret);
		return ret;
	}

	return 0;
}

int mtk_cfg80211_vndr_set_ap_mld_eml_mode(
	struct wiphy *wiphy,
	struct wireless_dev *wifi_dev,
	struct nlattr *data)
{
	struct nlattr *tb[MTK_NL80211_VENDOR_ATTR_AP_MLD_ATTR_MAX + 1];
	int ret;
	struct mt_cfg80211_vndr_ctrl ctrl_data, *ctrl_data_ptr = &ctrl_data;

	ret = nla_parse_nested(tb, MTK_NL80211_VENDOR_ATTR_AP_MLD_ATTR_MAX,
		(struct nlattr *)data, MTK_SUBCMD_SET_AP_MLD_EML_MODE_POLICY, NULL);

	if (ret) {
		MT_DEBUG_TRACE("eml mode parse failed, ret:%d\n", ret);
		return -EINVAL;
	}

        if (!tb[MTK_NL80211_VENDOR_ATTR_AP_MLD_INDEX]) {
		MT_DEBUG_TRACE("mld group index not exist\n");
		return -EINVAL;
	}

	ctrl_data_ptr->u8_val = nla_get_u8(tb[MTK_NL80211_VENDOR_ATTR_AP_MLD_INDEX]);

	if (nla_get_flag(tb[MTK_NL80211_VENDOR_ATTR_AP_MLD_EMLMR])) {
		ctrl_data_ptr->uint_val = MTK_NL80211_VENDOR_ATTR_AP_MLD_EMLMR;
	} else if (nla_get_flag(tb[MTK_NL80211_VENDOR_ATTR_AP_MLD_EMLSR])) {
		ctrl_data_ptr->uint_val = MTK_NL80211_VENDOR_ATTR_AP_MLD_EMLSR;
	} else {
		ctrl_data_ptr->uint_val = 0;
	}
	ctrl_data_ptr->sub_id = MTK_NL80211_VENDOR_ATTR_SET_AP_MLD_EML_MODE;

	ret = mt_cfg80211_vndr_cmd_handler(
		wiphy, wifi_dev, mt_cfg80211_vndr_attr_set_ap_mld, ctrl_data_ptr);
	if (ret < 0) {
		MT_DEBUG_TRACE("mt_cfg80211_vndr_cmd_handler for set ap mld eml_mode failed, ret:%d\n", ret);
		return ret;
	}

	return 0;
}

int mtk_cfg80211_vndr_doit_set_ap_mld(
	struct wiphy *wiphy, struct wireless_dev *wifi_dev, const void *data, int len)
{
	struct nlattr *tb[MTK_NL80211_VENDOR_ATTR_SET_AP_MLD_ATTR_MAX + 1];
	int ret;
	struct nlattr *attr;

	ret = nla_parse(tb, MTK_NL80211_VENDOR_ATTR_SET_AP_MLD_ATTR_MAX,
		(struct nlattr *)data, len, MTK_SUBCMD_SET_AP_MLD_POLICY, NULL);

	if (ret) {
		MT_DEBUG_TRACE("set ap mld parse failed, ret:%d\n", ret);
		return ret;
	}

	attr = tb[MTK_NL80211_VENDOR_ATTR_SET_AP_MLD_INDEX];
        if (attr) {
		ret = mtk_cfg80211_vndr_set_ap_mld_index(
			wiphy, wifi_dev, attr);
		if (ret) {
			MT_DEBUG_TRACE("set ap mld index failed, ret:%d\n", ret);
			return ret;
		}
	}

	attr = tb[MTK_NL80211_VENDOR_ATTR_SET_AP_MLD_ADDRESS];
	if (attr) {
		ret = mtk_cfg80211_vndr_set_ap_mld_addr(
			wiphy, wifi_dev, attr);
		if (ret) {
			MT_DEBUG_TRACE("set ap mld index failed, ret:%d\n", ret);
			return ret;
		}
	}

	attr = tb[MTK_NL80211_VENDOR_ATTR_SET_AP_MLD_EML_MODE];
	if (attr) {
		ret = mtk_cfg80211_vndr_set_ap_mld_eml_mode(
			wiphy, wifi_dev, attr);
		if (ret) {
			MT_DEBUG_TRACE("set ap mld eml_mode failed, ret:%d\n", ret);
			return ret;
		}
	}

	return 0;
}

