int mtk_cfg80211_vndr_doit_get_zr_hdo_rm(
	struct wiphy *wiphy, struct wireless_dev *wifi_dev, const void *data, int len)
	{
	struct nlattr *tb[MTK_NL80211_VENDOR_ATTR_ZR_HDO_RM_MAX + 1];
	int ret;
	struct mt_cfg80211_vndr_ctrl ctrl_data, *ctrl_data_ptr = &ctrl_data;

	ret = nla_parse(tb, MTK_NL80211_VENDOR_ATTR_ZR_HDO_RM_MAX, (struct nlattr *)data,
		len, MTK_SUBCMD_SET_ZR_HDO_RM_POLICY, NULL);

	if (ret)
		return -EINVAL;

	if (tb[MTK_NL80211_VENDOR_ATTR_ZR_HDO_RM_GET_STA_INFO]) {
		ctrl_data_ptr->data_len =
			nla_len(tb[MTK_NL80211_VENDOR_ATTR_ZR_HDO_RM_GET_STA_INFO]);
		ctrl_data_ptr->data =
			nla_data(tb[MTK_NL80211_VENDOR_ATTR_ZR_HDO_RM_GET_STA_INFO]);
		ctrl_data_ptr->sub_id = MTK_NL80211_VENDOR_ATTR_ZR_HDO_RM_GET_STA_INFO;
		ret = mt_cfg80211_vndr_cmd_get_handler(
			wiphy, wifi_dev, mt_cfg80211_vndr_attr_get_zr_hdo_rm,
			MTK_NL80211_VENDOR_ATTR_ZR_HDO_RM_GET_STA_INFO,ctrl_data_ptr);
		if (ret < 0)
			return ret;
	}
	return 0;
}
void mtk_cfg80211_vndr_init(struct wiphy *prWiphy)
{
	prWiphy->vendor_commands = mtk_vendor_commands;
	prWiphy->n_vendor_commands = ARRAY_SIZE(mtk_vendor_commands);
	prWiphy->vendor_events = mtk_vendor_events;
	prWiphy->n_vendor_events = ARRAY_SIZE(mtk_vendor_events);
}
EXPORT_SYMBOL(mtk_cfg80211_vndr_init); /* to-do: remove when no need. @20241209 */

